import sys,time,math,statistics,os
sys.path.insert(0,'/bot/src')
import robot2 as R

LOG=open('/memory/ep6.log','a')
SCAN=open('/memory/scan_ep6.log','a')
def L(s):
    try: LOG.write('%.1f %s\n'%(time.time()%100000,s)); LOG.flush()
    except Exception: pass

pose={'x':0.0,'y':0.0,'dist':0.0}
o0=None; hprev=None
def upd():
    global o0,hprev
    o1=R.odom()
    if o0 is None: o0=o1; return
    dl=o1[0]-o0[0]; dr=o1[1]-o0[1]
    if abs(dl)>500 or abs(dr)>500: o0=o1; return
    o0=o1
    d=(dl+dr)/2*0.00066
    pose['dist']+=abs(d)
    h=R.heading()
    if hprev is not None:
        dh=((h-hprev+180)%360)-180
        if abs(dh)>90: return
        pose['x']+=d*math.cos(math.radians(h))
        pose['y']+=d*math.sin(math.radians(h))
    hprev=h

GRID=set()
def med_lidar(n=2,tries=20):
    scans=[]
    for _ in range(tries):
        s=R.lidar()
        if len(s)==16: scans.append(s)
        if len(scans)>=n: break
        time.sleep(0.02)
    if not scans: return None
    return [statistics.median([s[i] for s in scans]) for i in range(16)]

def txstate():
    st=R.status()
    for tok in st.split():
        if tok.startswith('tx='):
            return tok.split(':')[1] if ':' in tok else '?'
    return '?'

BN={'n':0}
MSG1='B SEEKS A+GOAL. A: DRIVE STRAIGHT UNTIL YOU SEE ME. B DRIVES TOO. SAY SEE WHEN YOU SEE ME.'
MSG2='B WANDERING. IF YOU SEE A ROBOT ON LIDAR: STOP AND SAY SEE.'
MSG3='B-TO-A: WHERE ARE YOU? IF YOU SEE ME: DRIVE TO ME. I WILL TOO.'
def beacon(msg):
    BN['n']+=1
    try: R.tx('%s #%d'%(msg,BN['n']))
    except Exception: pass

def sig(n=4,dt=0.05):
    vs=[]
    for _ in range(n):
        v=R.fget('d11')
        if v>0: vs.append(v)
        time.sleep(dt)
    return statistics.median(vs) if vs else 0

def load_state():
    try:
        import json as _j
        d=_j.load(open('/memory/pose.json'))
        pose['x']=d['x']; pose['y']=d['y']; pose['dist']=d.get('dist',0)
        GRID.update(set(map(tuple,d.get('grid',[]))))
        L('loaded pose %.1f,%.1f cells=%d'%(pose['x'],pose['y'],len(GRID)))
    except Exception as e:
        L('no saved state (%r)'%e)

def save_state():
    try:
        import json as _j
        _j.dump({'x':pose['x'],'y':pose['y'],'dist':pose['dist'],'grid':sorted(list(GRID))[-6000:]},open('/memory/pose.json','w'))
    except Exception: pass

def turnto(tgt,sp=24,timeout=4):
    t0=time.time()
    while time.time()-t0<timeout:
        h=R.heading()
        err=((tgt-h+180)%360)-180
        if abs(err)<7: break
        if err>0: R.motors(sp,-sp)
        else: R.motors(-sp,sp)
        time.sleep(0.07)
    R.stop(); time.sleep(0.1)

def driveguard(dur=2.8,sp=20):
    t0=time.time()
    while time.time()-t0<dur:
        l=R.lidar()
        if len(l)==16:
            f=min([x for x in (l[15],l[0],l[1]) if x>0] or [9])
            if f<0.28: R.stop(); return False
        R.motors(sp,sp); time.sleep(0.07)
    R.stop(); return True

def pick(l,BAD):
    def b(i):
        v=l[i%16]; return v if v>0 else 2.5
    W={0:1.2,1:1.05,15:1.05,2:1.0,3:1.0,13:1.0,14:1.0,4:0.9,12:0.9,5:0.85,11:0.85,6:0.8,10:0.8,7:0.6,9:0.6,8:0.35}
    now=time.time()
    cands=[]
    for k in range(16):
        op=min(b(k),b((k-1)%16),b((k+1)%16))
        cands.append((op*W[k],k,op))
    cands.sort(reverse=True)
    for sc,k,op in cands:
        if BAD.get(k,0)<now-18: return k,op
    return cands[0][1],cands[0][2]

def blob(l):
    # narrow object: beam k short, both k-2,k+2 long
    def b(i):
        v=l[i%16]; return v if v>0 else -1
    hits=[]
    for k in range(16):
        v=b(k); p2=b(k-2); n2=b(k+2)
        if 0.15<v<1.2 and p2>v+0.35 and n2>v+0.35:
            hits.append((k,round(v,2)))
    return hits

def unjam():
    L('UNJAM')
    R.motors(-16,-16); time.sleep(1.2)
    l=med_lidar()
    if l:
        def b(i):
            v=l[i%16]; return v if v>0 else 2.5
        best=-1;bk=8
        for k in range(16):
            op=min(b(k),b((k-1)%16),b((k+1)%16))
            if op>best: best=op;bk=k
        turnto((R.heading()+bk*22.5)%360)
    R.motors(-13,-13); time.sleep(0.3)
    R.motors(20,20); time.sleep(1.8)
    R.stop()

def wander():
    BAD={}
    n=0; lastlog=0
    while True:
        n+=1
        l=med_lidar()
        if l is None: R.stop(); time.sleep(0.05); continue
        upd()
        GRID.add((int(pose['x']*2),int(pose['y']*2)))
        def b(i):
            v=l[i%16]; return v if v>0 else 2.5
        f=min(b(15),b(0),b(1))
        hits=blob(l)
        if hits:
            L('*** BLOB at %s pos=%.1f,%.1f h=%.0f ***'%(hits,pose['x'],pose['y'],R.heading()))
            SCAN.write('BLOB %.2f %.2f %.1f %s\n'%(pose['x'],pose['y'],R.heading(),','.join('%.2f'%v for v in l))); SCAN.flush()
            R.stop()
            for i in range(5):
                beacon('B SEES OBJECT AT BEAM %s. IF THAT IS YOU A: SAY ME. INVESTIGATING.'%(hits,))
                time.sleep(0.4)
            # creep toward blob
            k=hits[0][0]
            turnto((R.heading()+k*22.5)%360)
            driveguard(1.2,12)
            continue
        if f<0.18:
            R.motors(-14,-14); time.sleep(0.7); R.stop()
        k,op=pick(l,BAD)
        h=R.heading()
        if k==0:
            ok=driveguard(3.0,21)
        elif k in (1,15):
            bias=4 if k==1 else -4
            ok=driveguard_arc(2.6,bias)
        else:
            turnto((h+k*22.5)%360)
            ok=driveguard(2.6,21)
        if not ok: BAD[k]=time.time()
        if time.time()-lastlog>20:
            lastlog=time.time()
            s=sig(2,0.04)
            L('WAN pos=%.1f,%.1f k=%d ok=%s d11=%.3f tx=%s cells=%d'%(pose['x'],pose['y'],k,ok,s,txstate(),len(GRID)))
            SCAN.write('%.2f %.2f %.1f %s\n'%(pose['x'],pose['y'],R.heading(),','.join('%.2f'%v for v in l))); SCAN.flush()
            save_state()

def driveguard_arc(dur=2.6,bias=4,sp=21):
    t0=time.time()
    while time.time()-t0<dur:
        l=R.lidar()
        if len(l)==16:
            f=min([x for x in (l[15],l[0],l[1]) if x>0] or [9])
            if f<0.28: R.stop(); return False
        R.motors(sp+bias,sp-bias); time.sleep(0.06)
    R.stop(); return True

def main():
    load_state()
    L('EP6 start pos=%.1f,%.1f d11=%.3f tx=%s'%(pose['x'],pose['y'],sig(),txstate()))
    last_be=0; last_sum=0; msg_i=0
    last_moving=0
    while True:
        try:
            st=R.status_d()
            if st.get('here')=='1':
                L('*** HERE=1 %s'%st); R.stop()
                for i in range(10):
                    beacon('B AT GOAL. A COME NOW.')
