import time,statistics
def last(v):
    p=[x for x in v.split('\n') if x.strip()]
    return p[-1] if p else ''
def rd(p):
    for _ in range(8):
        v=last(open(f'/dev/robot/{p}').read())
        if v.strip(): return v
        time.sleep(0.02)
    return ''
def m(l,r):
    open('/dev/robot/d1','w').write(f'{l}\n'); open('/dev/robot/d7','w').write(f'{r}\n')
def hdg():
    for _ in range(15):
        v=rd('d4')
        try: return float(v)
        except: time.sleep(0.02)
    return None
def sample(n=10,dt=0.06):
    vs=[]
    for _ in range(n):
        v=rd('d11')
        try:
            f=float(v)
            if f>0: vs.append(f)
        except: pass
        time.sleep(dt)
    return statistics.median(vs) if vs else -1
def turnto(tgt,sp=24,timeout=3):
    t0=time.time()
    while time.time()-t0<timeout:
        h=hdg()
        if h is None: break
        err=((tgt-h+180)%360)-180
        if abs(err)<7: break
        if err>0: m(sp,-sp)
        else: m(-sp,sp)
        time.sleep(0.06)
    m(0,0); time.sleep(0.1)
def front():
    for _ in range(15):
        s=rd('d2')
        try:
            l=[float(x) for x in s.split(',')]
            if len(l)==16:
                return min([x for x in (l[15],l[0],l[1]) if x>0] or [9])
        except: pass
        time.sleep(0.03)
    return 0
def drive(dur=2.2,sp=20):
    t0=time.time()
    while time.time()-t0<dur:
        if front()<0.3: m(0,0); return False
        m(sp,sp); time.sleep(0.07)
    m(0,0); return True
h0=hdg()
print('hub heading %.0f'%h0)
s_hub=sample()
print('hub d11=%.3f'%s_hub)
res={}
for dd in (0,90,-90,180):
    tgt=(h0+dd)%360
    turnto(tgt)
    ok=drive(2.4,20)
    s=sample()
    res[dd]=(ok,s)
    print('dir %+d ok=%s d11=%.3f (delta %+.3f)'%(dd,ok,s,s-s_hub))
    # return to hub: reverse heading
    turnto((tgt+180)%360)
    if ok: drive(2.4,20)
    else: drive(1.0,20)
print('result',res)
print('hub again d11=%.3f'%sample())
EOF

