    R.stop()
    for i in range(8):
        beacon('B HERE. A: SAY ME. THEN FOLLOW ME TO GOAL.')
        t0=time.time()
        while time.time()-t0<0.8:
            m=R.rx()
            if m: L('RX %s'%m[:100])
            time.sleep(0.1)
    s0=sample()
    L('meet d11=%.3f'%s0)
    while True:
        if s0>0.85:
            L('*** ADJACENT d11=%.3f - hold+look ***'%s0)
            R.stop()
            for i in range(10):
