    def __init__(self):
        l9, l6 = R.odom()
        self.o9, self.o6 = l9, l6
        self.x = 0.0; self.y = 0.0
    def poll(self):
        l9, l6 = R.odom()
        d9 = l9 - self.o9; d6 = l6 - self.o6
        self.o9, self.o6 = l9, l6
        ds = (d9 + d6) / 2.0 * 0.00066
        h = math.radians(R.heading())
        self.x += ds * math.sin(h); self.y += ds * math.cos(h)
        return self.x, self.y

