    t0 = time.time()
    while time.time() - t0 < dur:
        vec.poll()
        if here(): R.stop(); return 'here'
        f = front()
        if f < 0.30:
            R.stop(); return 'blocked'
        R.motors(sp, sp)
        if msg: R.tx(msg)
        time.sleep(0.12)
